   269  /**
   270   * Find the normalized ijk coordinates of the indexing parent of a cell in a
   271   * counter-clockwise aperture 7 grid. Works in place.
   272   *
   273   * @param ijk The ijk coordinates.
   274   */
   275  void _upAp7(CoordIJK *ijk) {
   276      // convert to CoordIJ
   277      int i = ijk->i - ijk->k;
   278      int j = ijk->j - ijk->k;
   279
   280      ijk->i = (int)lroundl((3 * i - j) / 7.0L);
   281      ijk->j = (int)lroundl((i + 2 * j) / 7.0L);
   282      ijk->k = 0;
   283      _ijkNormalize(ijk);
   284  }
